local TweenService = game:GetService("TweenService")
local class = require(script.Parent.Parent.apis.class)
local BaseComponent = require(script.Parent.Parent.apis.BaseComponent)
local module = class(script.Name, BaseComponent)

function module:ctor(element)
	self.super.ctor(self, element)
end

function module:Init(hoverType)
    self:SetHoverScale()
end

function module:Dispose()
    self:CancelHoverScale()
end

-- 对UDim进行插值
local function Lerp(udim: UDim, alpha: number): UDim
    return UDim.new(udim.Scale * alpha, udim.Scale * alpha)
end

-- 对UDim进行插值
local function Lerp2(udim2: UDim2, alpha: number): UDim2
    return UDim2.new(Lerp(udim2.X, alpha), Lerp(udim2.Y, alpha))
end

-- 设置鼠标悬停至UI上时UI自动放大, 鼠标离开时UI自动还原
--[[
	checkUI: 检测鼠标悬停的UI, 该UI的大小决定检测区域大小
	expandUI: 要扩展的UI(需要有Size属性[Size为UDim2类型], 之后可能会适配其它UI控件)
	scale: 缩放系数
	transformTime: 放大或还原的过渡时间
	
	注意:win的Size属性不能受其它控件影响
]]
local function setUIExpand(
    checkUI: GuiObject,
    expandUI: GuiObject?,
    scale: number?,
    transformTime: number?)

    if expandUI == nil then expandUI = checkUI end
    if scale == nil then scale = 1.05 end
    if transformTime == nil then transformTime = 0.1 end

	local DEFAULT_SIZE = expandUI:GetAttribute("__defaultSize") -- 记录默认大小
    if not DEFAULT_SIZE then
        DEFAULT_SIZE = expandUI.Size
        expandUI:SetAttribute("__defaultSize", DEFAULT_SIZE)
    else
        expandUI.Size = DEFAULT_SIZE
    end

	local expandTween = nil
	local restoreTween = nil

	local c1 = checkUI.MouseEnter:Connect(function()
		-- 若正在缩小, 停止缩小动画, 并立即释放内存
		if restoreTween ~= nil then
			restoreTween:Destroy()
			restoreTween = nil 
		end

		-- 计算播放放大动画的时间
		local uiCurScale: number
		if DEFAULT_SIZE.X.Scale ~= 0 then
			uiCurScale = expandUI.Size.X.Scale / DEFAULT_SIZE.X.Scale
		elseif DEFAULT_SIZE.X.Offset ~= 0 then
			uiCurScale = expandUI.Size.X.Offset / DEFAULT_SIZE.X.Offset
		end
		local expandTransformTime = (1 - (uiCurScale - 1) / (scale - 1)) * transformTime

		-- 创建放大动画, 并播放
		local expandTweenInfo = TweenInfo.new(expandTransformTime)
		local expandTweenGoal = { Size = Lerp2(DEFAULT_SIZE, scale) }
		expandTween = TweenService:Create(expandUI, expandTweenInfo, expandTweenGoal)
		expandTween:Play()
	end)
	local c2 = checkUI.MouseLeave:Connect(function()
		-- 若正在放大, 停止放大动画, 并立即释放内存
		if expandTween ~= nil then
			expandTween:Destroy()
			expandTween = nil
		end

		-- 计算播放缩小动画的时间
		local uiCurScale: number
		if DEFAULT_SIZE.X.Scale ~= 0 then
			uiCurScale = expandUI.Size.X.Scale / DEFAULT_SIZE.X.Scale
		elseif DEFAULT_SIZE.X.Offset ~= 0 then
			uiCurScale = expandUI.Size.X.Offset / DEFAULT_SIZE.X.Offset
		end
		local restoreTransformTime = ((uiCurScale - 1) / (scale - 1)) * transformTime

		-- 创建缩小动画, 并播放
		local restoreTweenInfo = TweenInfo.new(restoreTransformTime)
		local restoreTweenGoal = { Size = DEFAULT_SIZE }
		restoreTween = TweenService:Create(expandUI, restoreTweenInfo, restoreTweenGoal)
		restoreTween:Play()
	end)

    return {c1, c2}
end

function module:OnHover(funcOrTable)
    local btn: ImageButton = self._element
    self:OffHover()
    if typeof(funcOrTable) == "function" then
        local enter = btn.MouseEnter:Connect(function(x, y)
            funcOrTable(true)
        end)
        local leave = btn.MouseLeave:Connect(function(x, y)
            funcOrTable(false)
        end)
        table.insert(self._hoverConnections, enter)
        table.insert(self._hoverConnections, leave)
    elseif typeof(funcOrTable) == "table" then
        local t = funcOrTable[1]
        if t == "Scale" then
            local hoverScale = funcOrTable[2]
            local target = funcOrTable[3] or btn
            local uiscale = target:FindFirstChild("_hoverScale")
            if uiscale then
                uiscale:Destroy()
            end
            uiscale = Instance.new("UIScale", target)
            uiscale.Name = "_hoverScale"
            uiscale.Scale = 1
            local enter = btn.MouseEnter:Connect(function(x, y)
                uiscale.Scale = 1
                TweenService:Create(uiscale, TweenInfo.new(0.3, Enum.EasingStyle.Back), {Scale = hoverScale}):Play()
            end)
    
            local leave = btn.MouseLeave:Connect(function(x, y)
                uiscale.Scale = hoverScale
                TweenService:Create(uiscale, TweenInfo.new(0.3, Enum.EasingStyle.Sine), {Scale = 1}):Play()
            end)
    
            table.insert(self._hoverConnections, enter)
            table.insert(self._hoverConnections, leave)
        end
    end
end

function module:OffHover()
    if not self._hoverConnections then
        self._hoverConnections = {}
    end
    if #self._hoverConnections > 0 then
        for _, c in pairs(self._hoverConnections) do
            c:Disconnect()
        end
        table.clear(self._hoverConnections)
    end
end

