        self._pressConnections = {}
    end
    if #self._pressConnections > 0 then
        for _, c in pairs(self._pressConnections) do
            c:Disconnect()
        end
        table.clear(self._pressConnections)
    end
end

function module:SetHoverScale(expandUI: GuiObject?, scale: number?, transformTime: number?)
    self:CancelHoverScale()

    local btn: ImageButton = self._element
    local scaleConnections = setUIExpand(btn, expandUI, scale, transformTime)

    if not self._scaleConnections then
        self._scaleConnections = {}
    end

    for _, c in pairs(scaleConnections) do
        table.insert(self._scaleConnections, c)
    end
end

function module:CancelHoverScale()
    if not self._scaleConnections then
        return
    end
    local btn: ImageButton = self._element
	local DEFAULT_SIZE = btn:GetAttribute("__defaultSize") -- 记录默认大小

    btn.Size = DEFAULT_SIZE

    for _, c in pairs(self._scaleConnections) do
        c:Disconnect()
    end

    table.clear(self._scaleConnections)
end

return module